namespace tests
{
    public class IOTests : IDisposable
    {
        private StringWriter _stdOutMock;

        private TextReader _stdIn;
        private TextWriter _stdOut;

        public IOTests()
        {
            this._stdIn = Console.In;
            this._stdOut = Console.Out;

            this._stdOutMock = new StringWriter();

            Console.SetOut(_stdOutMock);
        }

        /// <summary>
        /// Allows to test timeout behaviors
        /// </summary>
        /// <param name="timeoutMSec">The timeout in msecs</param>
        /// <param name="action">The function to call</param>
        /// <exception cref="TimeoutException">if timeout exceeded</exception>
        static void AssertCompletesBeforeTimeout(int timeoutMSec, Action action)
        {
            var task = Task.Run(action);
            var completedInTime = Task.WaitAll(new[] { task }, TimeSpan.FromMilliseconds(timeoutMSec));

            if (task.Exception != null)
            {
                if (task.Exception.InnerExceptions.Count == 1)
                {
                    throw task.Exception.InnerExceptions[0];
                }

                throw task.Exception;
            }

            if (!completedInTime)
            {
                throw new TimeoutException($"La soluzione non è ottimizzata (troppo lenta)");
            }
        }

        [Fact(DisplayName = "Menu (0,5 punti)")]
        public void TestMenu1()
        {
            char[] inputs = "ABCDX".ToCharArray();
            string expectedOutput = "A -> Esercizio 1\nB -> Esercizio 2\nC -> Esercizio 3\nD -> Esercizio 4\nX -> Esci dal programma\n";

            foreach (char input in inputs)
            {
                // Mock input
                StringReader stdInMock = new StringReader(input.ToString());
                Console.SetIn(stdInMock);

                char expectedChoice = input;
                char choice = lesson.Program.Menu();
                this._stdOutMock.Flush();

                string actualOutputLines = this._stdOutMock.ToString().Trim();
                string parsedExpectedOutput = expectedOutput.ReplaceLineEndings().Trim();

                Assert.Contains(parsedExpectedOutput, actualOutputLines);
                Assert.Equal(expectedChoice, choice);
            }

        }

        [Fact(DisplayName = "Menu 2 (0,5 punti)")]
        public void TestMenu2()
        {
            string expectedOutput = "A -> Esercizio 1\nB -> Esercizio 2\nC -> Esercizio 3\nD -> Esercizio 4\nX -> Esci dal programma\n";

            string invalidChars = "QWERTYUIOPSFGHJKLZVNM1234567890X";
            string invalidInputs = String.Join('\n', invalidChars.ToCharArray()) + '\n';

            expectedOutput = String.Join("", Enumerable.Repeat(expectedOutput, invalidChars.Length));

            // Mock input
            StringReader stdInMock = new StringReader(invalidInputs);
            Console.SetIn(stdInMock);

            char expectedChoice = invalidChars[invalidChars.Length - 1];
            char choice = lesson.Program.Menu();
            this._stdOutMock.Flush();

            string actualOutputLines = this._stdOutMock.ToString().ReplaceLineEndings().Trim();
            string parsedExpectedOutput = expectedOutput.ReplaceLineEndings().Trim();

            Assert.Equal(parsedExpectedOutput, actualOutputLines);
            Assert.Equal(expectedChoice, choice);
        }

