            int max = 10;
            int n = 2;
            int[] result = lesson.Program.Esercizio4(rnd, min, max, n);
            Assert.Equal(n, result.Length);
            foreach (var r in result) Assert.True(r >= min && r < max);
            var count = result.Distinct().Count();
            Assert.Equal(n, count);
        }

